select energy_manager.load_cards($cards$[
{"id":"p4-b12-026","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What heat outputs make up a rotary hearth furnace heat balance?","back":"Sensible heat of steel, sensible heat of scale, sensible heat of dry flue gas, heat lost to water vapour from fuel and from air, heat taken by cooling water, radiation losses, and an 'others' term that closes the balance.","explain":"In the case example, the balance is built per tonne of billet, so all outputs are compared on the same basis as the heat input.","flash":false,"source":"BEE Book 4 Ch 12 p253","order":4519},
{"id":"p4-b12-027","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What is the radiation heat loss formula for furnace openings used in the case example?","back":"Q (kcal/h) = hours × A (m²) × φ × 4.88 × [(T/100)⁴ − (Ta/100)⁴], with temperatures in kelvin. φ = 0.7 for a rectangular door.","explain":"The 4.88 is the radiation constant in these units, applied with (T/100)⁴ so temperatures in kelvin are scaled to hundreds. Wall and roof losses use a different form.","flash":false,"source":"BEE Book 4 Ch 12 p252","order":4520},
{"id":"p4-b12-028","paper":4,"topic":"Steel sector performance","kind":"fact","front":"What is the formula for surface (wall and roof) radiation loss per m² in the case example?","back":"Loss (kcal/m² h) = a × (t − ta)^1.25 + 4.88 × ε × [((t + 273)/100)⁴ − ((ta + 273)/100)⁴], with a = 2.2 for walls and 2.8 for the roof, and ε = 0.8.","explain":"The first term is convective and the second radiative. Surface temperatures and ambient are in °C in the first term and kelvin in the second.","flash":false,"source":"BEE Book 4 Ch 12 p252","order":4521},
{"id":"p4-b12-029","paper":4,"topic":"Steel sector performance","kind":"problem","front":"A rotary hearth furnace runs for 16 hours on a trial, producing 92 t of billet from 93.5 t of slab. Fuel is 5550 litres of LSHS (CV 10,200 kcal/kg, specific gravity 0.95), theoretical air is 14 kg/kg of fuel, flue gas O₂ is 4%, and atomising air is 700 Nm³/h at 1.28 kg/m³. Find the production rate, fuel rate, specific fuel consumption, total air and secondary air per tonne of billet.","back":"Production 5.75 t/h. Fuel 347 litres/h. SFC 57 kg fuel per t of billet. Total air 991 kg/t. Secondary air 835 kg/t.","explain":"Specific figures are per tonne of billet, so each hourly rate is divided by the production rate. Atomising air is part of the total air, so the balance is the secondary air.","flash":false,"source":"BEE Book 4 Ch 12 p249","steps":[{"prompt":"Production rate.","answer":"92 ÷ 16 = 5.75 t/h.","explain":"Total production over the 16-hour trial."},{"prompt":"Fuel rate and specific fuel consumption.","answer":"Fuel = 5550 ÷ 16 = 347 l/h. SFC = 347 ÷ 5.75 = 60 l/t, × 0.95 = 57 kg/t.","explain":"Litres converted to kg with specific gravity 0.95 (kg per litre)."},{"prompt":"Excess air from flue gas O₂.","answer":"Excess air = 4 ÷ (21 − 4) × 100 = 23.5%, taken as 24%.","explain":"Standard excess-air relation from O₂ in the flue gas."},{"prompt":"Total air supplied per tonne.","answer":"57 × 14 × (1 + 0.24) = 991 kg/t.","explain":"Fuel per tonne times theoretical air times (1 + excess)."},{"prompt":"Atomising air and secondary air per tonne.","answer":"Atomising: 700 × 1.28 = 896 kg/h ÷ 5.75 = 156 kg/t. Secondary: 991 − 156 = 835 kg/t.","explain":"Secondary air is the combustion air left after the atomising air is removed."}],"order":4522},
{"id":"p4-b12-030","paper":4,"topic":"Steel sector performance","kind":"problem","front":"For the rotary hearth furnace case, what are the total heat input and total heat output per tonne of billet, and what balances them?","back":"Input ≈ 6,07,926 kcal/t. Output ≈ 5,76,347 kcal/t, plus 31,579 kcal/t of 'others' to close the balance.","explain":"The book's combustion figure is slightly above 57 × 10,200 = 5,81,400 kcal/t, probably from an unrounded fuel rate. The book value is used here.","flash":false,"source":"BEE Book 4 Ch 12 p251","steps":[{"prompt":"Heat input from fuel combustion and sensible heat.","answer":"Combustion ≈ 5,84,560 kcal/t (book value). Fuel sensible heat = 57 × 0.5 × (100 − 30) ≈ 2006 kcal/t.","explain":"Fuel enters at 100 °C, against a 30 °C ambient reference."},{"prompt":"Heat of scale formation.","answer":"16 kg scale/t × 1335 kcal/kg Fe = 21,360 kcal/t.","explain":"Scale formation is exothermic, so it adds to the input."},{"prompt":"Total heat input.","answer":"5,84,560 + 2,006 + 21,360 = 6,07,926 kcal/t.","explain":"Atomising air and charged steel contribute zero because they enter at ambient, 30 °C."},{"prompt":"Sensible heat outputs in steel, scale and flue gas.","answer":"Steel: 1000 × 0.158 × 1270 = 2,00,660. Scale: 16 × 0.215 × 1270 = 4,369. Dry flue gas: (1048 − 62) × 0.26 × 645 = 1,65,389 kcal/t.","explain":"Steel and scale are heated from 30 °C to 1300 °C; flue gas leaves at 675 °C."},{"prompt":"Remaining outputs.","answer":"Water vapour from fuel 55,564; from air 10,433; cooling water 4869.6 × 10 = 48,696; radiation 91,236. Sum with the above = 5,76,347 kcal/t.","explain":"Cooling water per tonne = 28,000 ÷ 5.75 = 4869.6 kg, with a 10 °C rise."},{"prompt":"Balancing term.","answer":"6,07,926 − 5,76,347 = 31,579 kcal/t (about 5.2% of the input).","explain":"Unmeasured losses and measurement error are collected in this 'others' term."}],"order":4523},
{"id":"p4-b12-031","paper":4,"topic":"Steel sector performance","kind":"problem","front":"The rotary hearth furnace has two doors, each 1 m × 1 m, with radiation factor 0.7, at 1300 °C furnace and 30 °C ambient, running 1 hour. Find the radiation loss through the openings per tonne of billet at 5.75 t/h.","back":"About 72,643 kcal per tonne of billet, for both doors.","explain":"Radiation loss depends very strongly on temperature because it scales with the fourth power of absolute temperature. The openings dominate the furnace radiation loss.","flash":false,"source":"BEE Book 4 Ch 12 p252","steps":[{"prompt":"Convert temperatures to kelvin.","answer":"T = 1300 + 273 = 1573 K. Ta = 30 + 273 = 303 K.","explain":"The formula uses absolute temperatures."},{"prompt":"Loss per door per hour.","answer":"1 × 1 × 0.7 × 4.88 × [(15.73)⁴ − (3.03)⁴] = 208,847 kcal/h.","explain":"The brackets are in units of 100 K, matching the (T/100)⁴ terms."},{"prompt":"Both doors.","answer":"2 × 208,847 = 417,694 kcal/h.","explain":"Two identical openings add directly."},{"prompt":"Per tonne of billet.","answer":"417,694 ÷ 5.75 = 72,643 kcal/t.","explain":"Hourly loss divided by production rate."}],"order":4524},
{"id":"p4-b12-032","paper":4,"topic":"Steel sector performance","kind":"problem","front":"The furnace has a wall area of 78.5 m² and a roof area of 78.5 m², with average wall temperature 65 °C, roof 100 °C and ambient 30 °C. Find the wall and roof radiation losses per tonne of billet at 5.75 t/h, and the total radiation loss including the openings.","back":"Wall ≈ 5,009 kcal/t. Roof ≈ 13,584 kcal/t. Total radiation including openings ≈ 91,236 kcal/t.","explain":"Surface losses use a convective term plus a radiative term per m². The roof loss is larger because the roof runs hotter.","flash":false,"source":"BEE Book 4 Ch 12 p252","steps":[{"prompt":"Wall loss per m².","answer":"2.2 × (65 − 30)^1.25 + 4.88 × 0.8 × [(338/100)⁴ − (303/100)⁴] = 187.3 + 179.6 = 366.9 kcal/m² h.","explain":"First term convective, second radiative, with ε = 0.8."},{"prompt":"Wall loss per tonne.","answer":"78.5 × 366.9 = 28,801 kcal/h ÷ 5.75 = 5,009 kcal/t.","explain":"Per-m² loss times wall area, then divided by production rate."},{"prompt":"Roof loss per m².","answer":"2.8 × (100 − 30)^1.25 + 4.88 × 0.8 × [(373/100)⁴ − (303/100)⁴] = 567 + 428 = 995 kcal/m² h.","explain":"Roof uses coefficient 2.8 and the roof temperature of 100 °C."},{"prompt":"Roof loss per tonne.","answer":"78.5 × 995 = 78,108 kcal/h ÷ 5.75 = 13,584 kcal/t.","explain":"Same conversion as the wall."},{"prompt":"Total radiation loss.","answer":"72,643 (openings) + 5,009 (walls) + 13,584 (roof) = 91,236 kcal/t.","explain":"Radiation through openings is the largest single part."}],"order":4525},
{"id":"p4-b12-033","paper":4,"topic":"Steel sector performance","kind":"problem","front":"A plant makes 500 t/day of sponge iron and melts 88% of it into ingots. Base year (2011): coal 1.2 t/t SI at 5000 kcal/kg, power 120 kWh/t SI, captive heat rate 3500 kcal/kWh, melt shop 950 kWh/t ingot. Current year (2012): coal 1.1 t/t SI, power 100 kWh/t SI, heat rate 3200 kcal/kWh, melt shop 900 kWh/t ingot. Find the plant's specific energy consumption in million kcal per tonne of ingot for both years.","back":"Base year ≈ 10.62 million kcal/t of ingot. Current year ≈ 9.49 million kcal/t of ingot.","explain":"Plant SEC is total daily energy divided by ingot output, so sponge iron and melt shop energy are added before dividing by ingot tonnes.","flash":false,"source":"BEE Book 4 Ch 12 p254","steps":[{"prompt":"Sponge iron energy, base year.","answer":"1200 × 5000 + 120 × 3500 = 6.42 million kcal/t of sponge iron.","explain":"Coal kg per tonne times GCV, plus power kWh per tonne times heat rate."},{"prompt":"Ingot energy and ingot output, base year.","answer":"950 × 3500 = 3.325 million kcal/t of ingot. Ingot output = 500 × 0.88 = 440 t/day.","explain":"Melt shop power converted to heat, and 88% yield of sponge iron to ingot."},{"prompt":"Plant SEC, base year.","answer":"(6.42 × 500 + 3.325 × 440) ÷ 440 = (3210 + 1463) ÷ 440 = 10.62 million kcal/t.","explain":"Total daily energy divided by ingot output per day."},{"prompt":"Sponge iron and ingot energy, current year.","answer":"SI: 1100 × 5000 + 100 × 3200 = 5.82 million kcal/t. Ingot: 900 × 3200 = 2.88 million kcal/t.","explain":"Same method as the base year with current-year coal, power and heat rate."},{"prompt":"Plant SEC, current year.","answer":"(5.82 × 500 + 2.88 × 440) ÷ 440 = (2910 + 1267.2) ÷ 440 = 9.49 million kcal/t.","explain":"A lower SEC means less energy per tonne of finished ingot."}],"order":4526},
{"id":"p4-b12-034","paper":4,"topic":"Steel sector performance","kind":"problem","front":"Using the same sponge iron and ingot case, how much coal per day is saved in the current year compared with the base year, at a coal GCV of 5000 kcal/kg?","back":"About 495.8 million kcal/day saved, equal to about 99.16 t of coal per day.","explain":"The saving has two parts: the sponge iron step and the melt shop step. Both are converted to coal using the GCV of 5000 kcal/kg.","flash":false,"source":"BEE Book 4 Ch 12 p255","steps":[{"prompt":"Saving in sponge iron production.","answer":"(6.42 − 5.82) × 500 = 300 million kcal/day.","explain":"Difference in SEC times daily sponge iron output."},{"prompt":"Saving in the melt shop.","answer":"(3.325 − 2.88) × 440 = 195.8 million kcal/day.","explain":"Difference in ingot SEC times daily ingot output."},{"prompt":"Total saving.","answer":"300 + 195.8 = 495.8 million kcal/day.","explain":"Sum of the two savings."},{"prompt":"Equivalent coal saving.","answer":"495.8 × 10⁶ ÷ 5000 = 99,160 kg/day ≈ 99.16 t/day.","explain":"Energy saving divided by coal GCV gives coal mass."}],"order":4527},
{"id":"p4-b12-035","paper":4,"topic":"Steel sector performance","kind":"problem","front":"An annealing furnace has a charging door of 1.5 m² area at 800 °C, ambient 30 °C and radiation factor 0.75. Find its heat loss through the door per hour, using the chapter's radiation formula.","back":"About 72,310 kcal/h.","explain":"This applies the chapter's opening radiation formula. The exercise has no printed answer, so the result is worked from that formula.","flash":false,"source":"BEE Book 4 Ch 12 p256","steps":[{"prompt":"Convert temperatures to kelvin.","answer":"T = 800 + 273 = 1073 K. Ta = 303 K.","explain":"The radiation formula needs absolute temperatures."},{"prompt":"Constant term.","answer":"Area × factor × 4.88 = 1.5 × 0.75 × 4.88 = 5.49.","explain":"Time factor is 1 h."},{"prompt":"Temperature term.","answer":"(10.73)⁴ − (3.03)⁴ = 13,255.6 − 84.3 = 13,171.3.","explain":"Brackets use temperatures divided by 100."},{"prompt":"Heat loss per hour.","answer":"5.49 × 13,171.3 = 72,310 kcal/h.","explain":"Product of the constant and the temperature term."}],"order":4528},
{"id":"p4-b13-001","paper":4,"topic":"Cement Industry","kind":"fact","front":"Portland cement is the main cement type. Name four other cement types listed in the chapter.","back":"White, masonry, slag, aluminous and regulated-set cement.","explain":"Cement is a bonding agent that holds aggregate particles together to form concrete. Changing the percentages of CaO, Al₂O₃, Fe₂O₃, MgO and SiO₂ alters the physical and chemical properties of the cement.","flash":false,"source":"BEE Book 4 Ch 13 p259","order":4529},
{"id":"p4-b13-002","paper":4,"topic":"Cement Industry","kind":"fact","front":"What are the four basic stages of cement production?","back":"(1) Acquisition of raw materials, (2) preparation of raw materials for pyroprocessing, (3) pyroprocessing to form Portland clinker, (4) grinding clinker to Portland cement.","explain":"Clinker is the intermediate product: grey, glass-hard nodules formed in the rotary kiln. Grinding clinker with gypsum and other additives gives the finished cement.","flash":true,"source":"BEE Book 4 Ch 13 p259","order":4530},
{"id":"p4-b13-003","paper":4,"topic":"Cement Industry","kind":"fact","front":"How is limestone mined for cement, and why is surface mining gaining ground?","back":"Compressed-air drilling followed by explosive blasting in quarries. Surface mining is gaining ground because it is more eco-friendly.","explain":"Mined limestone reaches the plant by dumpers or ropeways. The raw material is the key input and is the first step of the process.","flash":false,"source":"BEE Book 4 Ch 13 p259","order":4531},
{"id":"p4-b13-004","paper":4,"topic":"Cement Industry","kind":"fact","front":"To what size do primary and secondary crushers reduce limestone, and what does a tertiary crusher add?","back":"About 25 mm. A tertiary crusher is now used to reduce the inlet size to the mill further.","explain":"Crushed limestone, bauxite and ferrite go to feed hoppers and then to the raw mill by weigh feeders in the required proportion.","flash":false,"source":"BEE Book 4 Ch 13 p259","order":4532},
{"id":"p4-b13-005","paper":4,"topic":"Cement Industry","kind":"fact","front":"What coal size and fineness does the coal mill need to produce?","back":"80% on 90 micron and less than 2% on 212 micron.","explain":"Coal mills can be air-swept ball mills or vertical roller mills with a grit separator and bag filter. Drying heat comes from a coal-fired furnace or from clinker cooler or preheater exhaust.","flash":true,"source":"BEE Book 4 Ch 13 p260","order":4533},
{"id":"p4-b13-006","paper":4,"topic":"Cement Industry","kind":"fact","front":"At roughly what temperatures do evaporation, dehydration, calcination and clinker formation happen in the kiln?","back":"Evaporation up to 100 °C; dehydration 100 to about 430 °C; calcination (CO₂ released) 900 to 982 °C; clinker reactions in the burning zone near 1510 °C.","explain":"Calcination converts CaCO₃ to CaO and releases CO₂, the main greenhouse gas from the process. Clinker forms as grey, glass-hard, spherical nodules of 0.32 to 5.1 cm.","flash":false,"source":"BEE Book 4 Ch 13 p260","order":4534},
{"id":"p4-b13-007","paper":4,"topic":"Cement Industry","kind":"fact","front":"Name the four main clinker compounds formed in the kiln.","back":"C₃S, C₂S, C₃A and C₄AF.","explain":"The burning zone reacts silica, alumina, ferric oxide and calcium oxide (free lime) to form these compounds.","flash":false,"source":"BEE Book 4 Ch 13 p260","order":4535},
{"id":"p4-b13-008","paper":4,"topic":"Cement Industry","kind":"fact","front":"How does a preheater improve on a simple rotary kiln?","back":"Cyclones in series in a tower: hot kiln gases pass counter-current to the falling raw meal. Heat transfer rises, heat use is more complete, process time falls, and a kiln can be shorter.","explain":"Better heat transfer means a retrofitted kiln can increase output without lengthening the kiln.","flash":false,"source":"BEE Book 4 Ch 13 p260","order":4536},
{"id":"p4-b13-009","paper":4,"topic":"Cement Industry","kind":"fact","front":"In a preheater/precalciner kiln, what minimum share of the thermal energy is still required in the rotary kiln?","back":"At least 40%.","explain":"Part of the fuel is burned in a precalciner at the base of the preheater tower, which is why the kiln itself needs less than the full thermal load.","flash":false,"source":"BEE Book 4 Ch 13 p260","order":4537},
{"id":"p4-b13-010","paper":4,"topic":"Cement Industry","kind":"fact","front":"What share of the raw meal is calcined before it enters the kiln in a precalciner system?","back":"Up to 95%.","explain":"Calciner systems sometimes use lower-quality fuels (for example, less volatile matter) to improve process economics.","flash":false,"source":"BEE Book 4 Ch 13 p262","order":4538},
{"id":"p4-b13-011","paper":4,"topic":"Cement Industry","kind":"fact","front":"How is preheater and precalciner exit gas split, and how is particulate matter removed?","back":"60% goes to the raw mill and 40% to a conditioning tower where water is injected. The gases then pass through an electrostatic precipitator (ESP) for maximum particulate removal.","explain":"Conditioning cools and prepares the gas before the ESP. The raw mill uses the gas for drying and sweeping.","flash":false,"source":"BEE Book 4 Ch 13 p262","order":4539},
{"id":"p4-b13-012","paper":4,"topic":"Cement Industry","kind":"fact","front":"What are the two tasks of the clinker cooler?","back":"Recover as much heat as possible from the hot clinker and return it to the process, and reduce the clinker temperature to a level suitable for downstream equipment.","explain":"Clinker cools from about 1450 °C to 130 °C in a grate cooler with a series of fans. Rapid cooling maximises the yield of the compounds that give cement its hardening properties.","flash":true,"source":"BEE Book 4 Ch 13 p262","order":4540},
{"id":"p4-b13-013","paper":4,"topic":"Cement Industry","kind":"fact","front":"Where does the hot air recuperated from the clinker cooler go?","back":"Secondary air is the main burning air for the kiln. Tertiary air is used as precalciner fuel air. The remaining air goes to the stack through multiclones or an ESP.","explain":"Recuperation of cooler heat is one of the main energy-saving levers in the cooler, so maximum recuperation with controlled airflow is the target.","flash":false,"source":"BEE Book 4 Ch 13 p262","order":4541},
{"id":"p4-b13-014","paper":4,"topic":"Cement Industry","kind":"fact","front":"Why is gypsum blended with ground clinker in finish milling?","back":"It controls the rate of hydration in the cement-setting process.","explain":"Finish milling grinds clinker and additives into a fine grey powder in a closed circuit with an air separator. Under-ground material goes round the circuit again.","flash":false,"source":"BEE Book 4 Ch 13 p262","order":4542},
{"id":"p4-b13-015","paper":4,"topic":"Cement Industry","kind":"fact","front":"What unit measures cement fineness, and what is the typical Blaine value for Portland cement?","back":"Blaine, in cm²/g (total surface area per gram). Portland cement is typically 3000 to 3500 cm²/g.","explain":"A higher Blaine means more finely ground cement, which needs more grinding energy.","flash":true,"source":"BEE Book 4 Ch 13 p262","order":4543},
{"id":"p4-b13-016","paper":4,"topic":"Cement Industry","kind":"fact","front":"What share of cement production cost does energy account for?","back":"About 40 to 50%.","explain":"Many cement plants in developing countries consume far more energy per tonne than the best achieved figures in developed countries, so the savings potential is large.","flash":false,"source":"BEE Book 4 Ch 13 p262","order":4544},
{"id":"p4-b13-017","paper":4,"topic":"Cement Industry","kind":"fact","front":"Roughly how is electrical energy split across finish grinding, clinker burning and the raw mill?","back":"About 30% for finish grinding, below 30% for clinker burning, and about 24% for the raw mill circuit.","explain":"Major electrical consumers are mill drives, fans and conveying systems. Finish grinding and the raw mill mainly use power for the mill; clinker burning mainly uses power for fans.","flash":false,"source":"BEE Book 4 Ch 13 p262","order":4545},
{"id":"p4-b13-018","paper":4,"topic":"Cement Industry","kind":"fact","front":"Which fuels are used in a cement plant, and where is most thermal energy used?","back":"Coal, pet coke, gas and oil, plus unconventional fuels such as used tyres, incinerable hazardous wastes and agro residues. Most thermal energy is used in the kiln and precalciner.","explain":"Thermal energy is almost half of the energy cost of cement manufacture. Coal-fired plants also use an external coal or oil furnace to heat air for the coal mills.","flash":false,"source":"BEE Book 4 Ch 13 p263","order":4546},
{"id":"p4-b13-019","paper":4,"topic":"Cement Industry","kind":"fact","front":"What were the best reported Indian cement plant values in 2008-09 (NECA 2009), electrical and thermal?","back":"66.2 kWh per tonne of cement (electrical) and 687 kcal/kg clinker (thermal).","explain":"Table 13.1 compares India average with world best practice by process; for example, thermal energy is 770 kcal/kg clinker on average against 680 for world best. Specific energy depends on raw meal quality, fuel quality, preheater stages, blending, fineness and plant vintage.","flash":true,"source":"BEE Book 4 Ch 13 p264","order":4547},
{"id":"p4-b13-020","paper":4,"topic":"Cement Industry","kind":"fact","front":"What is a kiln heat balance used for?","back":"To optimise kiln operation, diagnose operating problems, increase production, improve energy consumption, lower emissions and increase refractory life.","explain":"The heat output values from the preheater, kiln and cooler are compared with standard values to find where energy is being lost.","flash":false,"source":"BEE Book 4 Ch 13 p264","order":4548},
{"id":"p4-b13-021","paper":4,"topic":"Cement Industry","kind":"fact","front":"On what basis is the kiln heat balance (indirect method) in Example 13.1 calculated?","back":"Basis of 1 kg of clinker. Heat output is compared with heat input.","explain":"The indirect method sums the heat outputs (heat of formation, exit gases, clinker, cooler exhaust, moisture evaporation, incomplete combustion, radiation and convection losses) and balances them against the inputs.","flash":false,"source":"BEE Book 4 Ch 13 p265","order":4549},
{"id":"p4-b13-022","paper":4,"topic":"Cement Industry","kind":"fact","front":"In the typical kiln heat balance, how much heat goes to chemical reaction, and how much is lost?","back":"Of 771 kcal/kg clinker, 404 kcal/kg is for chemical reaction. The remaining 367 kcal/kg is losses, and 75% of those losses go through the kiln and cooler stacks.","explain":"The book's challenge is to reduce these exhaust-gas losses. Significant abnormal heat loss is almost always linked to preheater and/or cooler exhaust.","flash":true,"source":"BEE Book 4 Ch 13 p272","order":4550},
{"id":"p4-b13-023","paper":4,"topic":"Cement Industry","kind":"fact","front":"How can cooler exhaust heat loss be reduced?","back":"Maximise heat recuperation by controlling air flow, clinker distribution and clinker granulometry. Minimise false air into the firing hood and at the kiln discharge seal.","explain":"Other exhaust-loss measures in the chapter: reduce CO formation with good main-burner combustion, reduce precalciner gas quantity, reduce preheater exit temperature with good meal distribution and high cyclone efficiency.","flash":false,"source":"BEE Book 4 Ch 13 p273","order":4551},
{"id":"p4-b13-024","paper":4,"topic":"Cement Industry","kind":"fact","front":"According to the chapter's note on over-burning, how much heat can 0.1% of free lime below the optimum waste?","back":"Up to 14 kcal/kg clinker.","explain":"Over-burning is avoided by keeping kiln feed chemistry consistent and feed and fuel rates constant. Minimising false air at kiln seals and preheater ports also helps.","flash":true,"source":"BEE Book 4 Ch 13 p273","order":4552},
{"id":"p4-b13-025","paper":4,"topic":"Cement Industry","kind":"fact","front":"What must the raw mill produce, and what hot gas dries and sweeps it?","back":"Kiln feed that meets targets for fineness, chemical composition and moisture. Preheater exhaust gas at about 290 to 300 °C dries and sweeps the mill.","explain":"Drying is also aided by heat from mill drive power, roughly 1 tonne of moisture per 1000 kWh. The fine powder is carried by kiln gases to multiclones and bag filters.","flash":false,"source":"BEE Book 4 Ch 13 p273","order":4553},
{"id":"p4-b13-026","paper":4,"topic":"Cement Industry","kind":"fact","front":"What specific power do ball mills and vertical roller mills need for raw grinding?","back":"Ball mills: about 10 kWh/t for soft, chalky limestone, up to about 25 kWh/t for hard materials. Vertical roller mills: about 4.5 to 8.5 kWh/t, with system power about 30% lower than a ball mill.","explain":"Specific power depends on material hardness and mill efficiency. ID fan power is higher with a roller mill, but total system power is still generally lower.","flash":false,"source":"BEE Book 4 Ch 13 p273","order":4554},
{"id":"p4-b13-027","paper":4,"topic":"Cement Industry","kind":"fact","front":"In the raw mill heat balance example, what share of heat output goes to evaporating moisture, and what share of heat input comes from the preheater gas?","back":"Moisture evaporation is 39.57% of output. Hot preheater gas is 69.98% of input.","explain":"Figure 13.4 also shows heat to raw material 17.8%, heat to dedusting gas 30.25%, radiation loss 8.33% and false air loss 4.05% of output.","flash":false,"source":"BEE Book 4 Ch 13 p276","order":4555},
{"id":"p4-b13-028","paper":4,"topic":"Cement Industry","kind":"fact","front":"What is the Pitot-tube formula for gas velocity in a duct?","back":"V = Cp × √(2g × ΔP / ρ), where Cp is the Pitot coefficient (0.844 in the book's example), g = 9.81 m/s², ΔP is the velocity pressure and ρ is the gas density at prevailing conditions.","explain":"Volumetric flow = velocity × duct area. The book converts m³/s to Nm³/h by multiplying by 3600 × (ρ at prevailing conditions ÷ ρ at STP).","flash":false,"source":"BEE Book 4 Ch 13 p267","order":4556},
{"id":"p4-b13-029","paper":4,"topic":"Cement Industry","kind":"fact","front":"How is gas density corrected from STP to the prevailing temperature and static pressure?","back":"ρ = ρ(STP) × (10334 − Ps)/10334 × 273/(273 + t), with Ps in mmWC (static pressure) and t in °C. The 10334 mmWC standard pressure is adjusted for plant altitude.","explain":"Air at STP is 1.293 kg/Nm³. Preheater exit gas density comes from its gas analysis (1.436 kg/Nm³ in Example 13.1), so the same correction applies to both.","flash":false,"source":"BEE Book 4 Ch 13 p267","order":4557},
{"id":"p4-b13-030","paper":4,"topic":"Cement Industry","kind":"fact","front":"What is the formula for the heat of evaporation of kiln feed moisture in the heat balance?","back":"Q = m × [(100 − t_kf) + L + Cp × (t − 100)], where m is the kiln feed moisture per kg clinker, t_kf the kiln feed temperature, L the latent heat (540 kcal/kg) and Cp the steam specific heat (0.457).","explain":"The same form is used for the moisture in fine coal, with the coal's own moisture fraction. Both are heat outputs in the balance.","flash":false,"source":"BEE Book 4 Ch 13 p268","order":4558},
{"id":"p4-b13-031","paper":4,"topic":"Cement Industry","kind":"fact","front":"What is the formula for radiation heat loss from a kiln or duct surface?","back":"Radiation loss = σ × ε × (T⁴ − Tₐ⁴) × surface area (kcal/h), with σ = 4.88 × 10⁻⁸ kcal/m²·h·K⁴ and ε = 0.80 for oxidised steel.","explain":"Temperatures are absolute (K). Surface temperatures are measured at 1 m intervals along the kiln and the tertiary air duct, and each section is summed.","flash":false,"source":"BEE Book 4 Ch 13 p269","order":4559},
{"id":"p4-b13-032","paper":4,"topic":"Cement Industry","kind":"fact","front":"What is the convection loss formula for wind velocity of 3 m/s or more?","back":"Convection loss = (5.86 + 3.04 × wind velocity) × (T_surface − T_ambient) × surface area (kcal/h).","explain":"For wind velocity of 3 m/s or less, the book uses a different correction. The worked example assumes 1.5 m/s wind.","flash":false,"source":"BEE Book 4 Ch 13 p269","order":4560}
]$cards$::jsonb);
